import {e,field,select,editAttrs} from '../creative-kit/ui.js?v=0.22.0';
import {MAX_CRITERIA,CRITERION_KINDS,JUDGEMENTS,assessmentFor,assessmentStatus,needsReassessment} from './criteria.js?v=0.22.0';

const title = d => d.title || 'Untitled alternative';
const label = row => row.label || 'Unnamed criterion';
function cell(row,d){
  const a=assessmentFor(d,row.id),judgement=JUDGEMENTS[a?.judgement??'unknown'];
  return `<td><button class="criterion-cell" data-action="assess-criterion" data-id="${e(d.id)}" data-criterion="${e(row.id)}" aria-label="Assess ${e(title(d))} against ${e(label(row))}"><strong>${judgement}</strong><span class="criterion-record ${needsReassessment(row,a)?'needs-review':''}">${assessmentStatus(row,a)}</span><span class="criterion-reason">${e(a?.reason||'Add a reason or name what is still unknown.')}</span><span class="criterion-edit">Assess →</span></button></td>`;
}
export function criteriaComparison(w){
  const rows=w.criteriaRows.filter(row=>row.active),retired=w.criteriaRows.filter(row=>!row.active),designs=w.comparison.map(id=>w.designs.find(d=>d.id===id));
  return `<section class="criterion-comparison" aria-labelledby="criterion-heading"><div class="section-head"><div><h3 id="criterion-heading">Compare what matters</h3><p>Separate hard constraints from preferences. Keep unknowns and the reasons for each judgement visible.</p></div><button data-action="add-criterion" ${w.criteriaRows.length>=MAX_CRITERIA?'disabled':''}>+ Criterion</button></div>${rows.length&&designs.length?`<p class="pan-hint" id="criterion-pan-hint">Scroll sideways through the alternatives ↔. Select a cell to assess it.</p><div class="criterion-scroll" tabindex="0" role="region" aria-label="Criterion comparison; scroll sideways" aria-describedby="criterion-pan-hint"><table class="criterion-table" style="--criterion-columns:${designs.length}"><thead><tr><th scope="col">Criterion</th>${designs.map(d=>`<th scope="col">${e(title(d))}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr><th scope="row"><span class="criterion-kind">${CRITERION_KINDS[row.kind]}</span><strong>${e(label(row))}</strong><button class="text-button" data-action="edit-criterion" data-id="${e(row.id)}" aria-label="Edit criterion ${e(label(row))}">Edit criterion</button></th>${designs.map(d=>cell(row,d)).join('')}</tr>`).join('')}</tbody></table></div>`:rows.length?`<p>Choose alternatives above to assess them against these criteria.</p><div class="criterion-list">${rows.map(row=>`<button data-action="edit-criterion" data-id="${e(row.id)}">${e(label(row))}<span>${CRITERION_KINDS[row.kind]}</span></button>`).join('')}</div>`:'<p class="empty">Add a criterion to compare each option against the same condition. Your overall comparison notes stay available above.</p>'}${retired.length?`<details class="retired-criteria"><summary>Retired criteria · ${retired.length}</summary><p>Assessments stay in this workspace and its exports. Restore a criterion to compare it again.</p><div class="criterion-list">${retired.map(row=>`<button data-action="edit-criterion" data-id="${e(row.id)}">${e(label(row))}<span>${CRITERION_KINDS[row.kind]} · retired</span></button>`).join('')}</div></details>`:''}</section>`;
}
export function editCriterion(id,k){
  const w=k.w(),row=w.criteriaRows.find(row=>row.id===id);if(!row)return;
  const used=w.designs.some(d=>assessmentFor(d,id));
  k.open(`${field('criterion-label','What must an option satisfy?',row.label,editAttrs('criterion-rows',id,'label'),'Use an observable condition, such as “Can be tried within one week”.')}${select('criterion-kind','How does this condition affect the decision?',row.kind,CRITERION_KINDS,editAttrs('criterion-rows',id,'kind'))}<p class="hint">A hard constraint is a condition you say an option must meet. Changing its wording or type asks for reassessment; earlier reasons remain.</p><div class="toolbar"><button class="primary" data-action="close">Done</button><button data-action="retire-criterion" data-id="${e(id)}">${row.active?'Retire criterion':'Restore criterion'}</button><button class="text-button delete" data-action="remove-criterion" data-id="${e(id)}" ${used?'disabled title="Retire this criterion to retain its assessments."':''}>Remove unused criterion</button></div>`,'Edit criterion');
}
export function assessCriterion(designId,criterionId,k){
  const w=k.w(),row=w.criteriaRows.find(row=>row.id===criterionId),d=w.designs.find(d=>d.id===designId);if(!row||!d)return;
  const a=assessmentFor(d,criterionId),item=`${designId}:${criterionId}`;
  k.open(`<p class="criterion-kind">${CRITERION_KINDS[row.kind]}${row.active?'':' · retired'}</p><h3 class="criterion-dialog-label">${e(label(row))}</h3><p>Alternative: <strong>${e(title(d))}</strong></p>${needsReassessment(row,a)?'<p class="review-note">This assessment needs another look. Its criterion or alternative changed, or its writing has not been recorded yet.</p>':''}${a?.reviewed?`<details class="criterion-reviewed"><summary>Criterion at the last recorded assessment</summary><p>${e(a.reviewed.label)}</p><p class="hint">${CRITERION_KINDS[a.reviewed.kind]}</p></details>`:''}${select('criterion-judgement','Your judgement',a?.judgement??'unknown',JUDGEMENTS,editAttrs('criterion-assessments',item,'judgement'))}${field('criterion-reason','Reason, evidence or what is still unknown',a?.reason??'',editAttrs('criterion-assessments',item,'reason'),'Explain the judgement. If it is unknown, name what you need to find out.')}<p class="hint">Edits stay as a draft until you record this assessment against the current criterion. These are your judgements; they do not produce a score or choose an option.</p><div class="toolbar"><button class="primary" data-action="record-assessment" data-id="${e(designId)}" data-criterion="${e(criterionId)}">Record assessment</button><button data-action="close">Close</button></div>`,'Assess the alternative');
}
